(4797414, 693791, 21500, '<td valign="top">exposure seems too low for everything outside the subject - that''s a difficult shot given how bright the sky is and how dark the parking lot and car are.</td>', 'exposure seems too low for everything outside the subject - that''s a difficult shot given how bright the sky is and how dark the parking lot and car are.', '2008-07-02 08:39:23.000000', NULL, 1),
(4797427, 694358, 21500, '<td valign="top">This looks like it might have been taken on a weekend - many buildings leave their lights on during weeknights but turn them out over the weekend.  If you get them with their lights on (weeknight) it adds more detail and reduces contrast with the street lights.  Nice shot.</td>', 'This looks like it might have been taken on a weekend - many buildings leave their lights on during weeknights but turn them out over the weekend.  If you get them with their lights on (weeknight) it adds more detail and reduces contrast with the street lights.  Nice shot.', '2008-07-02 08:45:03.000000', NULL, 1),
(4797432, 693007, 21500, '<td valign="top">nice lighting</td>', 'nice lighting', '2008-07-02 08:46:32.000000', NULL, 1),
(4797438, 692680, 21500, '<td valign="top">Go Birds!  <br/>Seems a little under exposed.  One suggestion is to shoot during weeknights rather than weekends because office towers generally leave their lights on during weeknights, but not weekends.</td>', 'Go Birds!  Seems a little under exposed.  One suggestion is to shoot during weeknights rather than weekends because office towers generally leave their lights on during weeknights, but not weekends.', '2008-07-02 08:48:03.000000', NULL, 1),
